#include "Parameters.h"
#include "Arpeggio.h"
#include <iostream>
#include <stdexcept>
void check(bool ok,const char* m){if(!ok)throw std::runtime_error(m);}
int main(){try{nova::Sound s;s.sampleRate=8000;s.left.resize(24000);s.right=s.left;int notes[]={60,64,67,72};for(size_t i=0;i<s.left.size();++i){int step=std::min(15,static_cast<int>(i/1500));int note=notes[step%4];double hz=440*std::pow(2.,(note-69)/12.);s.left[i]=s.right[i]=static_cast<float>(.35*std::sin(2*nova::pi*hz*i/s.sampleRate));}auto a=nova::detectArpeggio(s);check(a.valid&&a.root==60&&a.count>=14,"monophonic pattern detection");for(int i=0;i<16;++i)check(std::abs(a.notes[i]-(notes[i%4]-60))<=1,"pitch sequence");check(std::abs(a.bpm-80)<.1,"tempo 16 steps");nova::ArpClock clock;std::array<int,16> pattern{};pattern.fill(nova::arpRest);pattern[0]=0;pattern[1]=4;int on=0,off=0,rendered=0,last=-1;auto noteOn=[&](int,int note,float){++on;last=note;};auto noteOff=[&](int,int){++off;};auto output=[&](int,int n){rendered+=n;};auto get=[&](int i){return pattern[i];};clock.start(1,60,1,noteOff);clock.render(3200,8000,120,get,noteOn,noteOff,output);check(on==2&&off==2&&rendered==3200&&last==64,"timed steps and rests");clock.stop(1,60,noteOff);check(!clock.held,"note release stops arpeggio");clock.reset();
 nova::Params p;p.unison=false;p.waveA=0;p.waveB=0;p.mix=0;p.sub=p.noise=p.fm=0;p.cutoff=20000;p.envAmount=p.resonance=0;p.attack=.001f;p.sustain=1;p.master=-12;p.reverb=p.delay=p.chorus=0;std::vector<float> l(24000),r(24000),aout(24000);nova::Engine engine;engine.configure(p);engine.prepare(48000);engine.noteOn(1,60,1);engine.render(l.data(),r.data(),24000);p.boost=6;engine.configure(p);engine.prepare(48000);engine.noteOn(1,60,1);engine.render(aout.data(),r.data(),24000);double quiet=0,loud=0;for(int i=16000;i<24000;++i){quiet+=l[i]*l[i];loud+=aout[i]*aout[i];}check(loud/quiet>3.9&&loud/quiet<4.1,"gain raises output by six dB");
 s.left.assign(24000,0);s.right=s.left;check(!nova::detectArpeggio(s).valid,"silence rejected");std::cout<<"PASS: 16 editable monophonic steps, root, tempo, silence\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
